// ─────────────────────────────────────────────────────────────────
// NEARBY EATS DATA
// A hand-curated list of restaurants — no crowdsourcing, no
// submissions. Each entry's lat/lon is geocoded once (from its zip)
// at authoring time, so a search only needs to geocode the visitor's
// own zip or city, then it's just distance math against this list.
//
// To add a restaurant: look up its zip's coordinates (e.g. visiting
// https://api.zippopotam.us/us/<zip> in a browser gives you
// "latitude"/"longitude" directly — swap "us" for another country
// code, e.g. "es", for non-US zips), then add an entry below.
//
// cuisines is its own list here, not Recipe Finder's — it adds
// "spanish", "bakery", "bbq", and "seafood" on top of the shared base
// set, since those come up for restaurants but not home recipes.
//
// mealTypes: which of "breakfast" | "lunch" | "dinner" the place is
// realistically open for, based on its posted hours — used by the
// meal filter. hours/knownFor are just display text, not parsed.
//
// source: where an entry's trust comes from — every entry needs one:
//   "personal" — Joseph named it himself (whether he's eaten there
//                or knows it by reputation). No rating bar; this is
//                the default and covers almost everything here.
//   "chain"    — a well-known multi-location chain (Chick-fil-A,
//                IHOP, Cava, Chopt, Mission BBQ, Bareburger, Sweet
//                Paris) where brand consistency is the trust
//                mechanism, not one specific visit.
//   "vetted"   — a restaurant sourced independently (e.g. by Claude,
//                filling a geographic gap) with no personal backing
//                from Joseph. These must clear 4.6★+ AND 200+
//                reviews on at least one of Yelp, Google, or
//                Tripadvisor, with recent reviews specifically
//                checked for signs of decline (not just the all-time
//                average) before being added — OR carry a real James
//                Beard Foundation award/nomination (Best Chef winner,
//                America's Classics, etc.), which substitutes for the
//                rating bar since a JBF credential is itself a
//                stronger signal than aggregate stars. Carries a
//                `vetting: { rating, reviewCount, asOf, platform }`
//                object as the receipt for the review-based check —
//                platform is whichever of "Yelp" | "Google" |
//                "Tripadvisor" actually cleared the bar (checked in
//                that order; Yelp preferred when it has enough data)
//                — and the frontend shows a "not personally visited"
//                badge naming that platform on these. A JBF-qualified
//                entry additionally carries a plain-text
//                `recognition` field (e.g. "James Beard Award — Best
//                Chef South Winner, 2022") shown as its own badge line.
//                IMPORTANT: this bar only applies when the
//                restaurant is being sourced independently — if
//                Joseph names a restaurant himself, it's "personal"
//                regardless of its public rating.
//
// diningStyle: one of RESTAURANT_STYLE_OPTIONS ("fine-dining" |
// "fast-food" | "comfort") — every entry has one, used by the style
// filter. Backfilled programmatically from priceLevel, source, and
// keywords in knownFor/name; treat it as a reasonable default rather
// than a hand-verified fact, since most entries predate this field.
//
// priceLevel: 1-5 integer ($ to $$$$$), rendered as filled/empty $
// marks and used by the budget filter ("this or cheaper"). Every
// entry has one, but most were backfilled programmatically rather
// than individually researched — treat it the same way as
// diningStyle, a reasonable estimate, not a verified menu price:
// national chains (Chick-fil-A, IHOP, etc.) got a real-world price
// per brand; a small set of "fine-dining"-tagged entries were hand-
// reviewed individually; everything else defaulted off diningStyle
// (fast-food -> 1, fine-dining -> 4) with a couple of cuisine-based
// nudges for "comfort" entries (bakery -> 1, seafood -> 3, else 2).
//
// Optional fields, shown in the click-to-expand detail modal (most
// are omitted from most existing entries — the frontend just skips
// whatever's missing):
//   address    — street address, shown above the zip in the modal.
//   tip        — a specific recommendation (what to order, an
//                off-menu item, a reservation trick). Mostly makes
//                sense on "personal" entries, where it's Joseph's own
//                tip, but nothing stops a "vetted" entry from having
//                one if a standout dish came up during sourcing.
//   recognition — plain-text award credential (see "vetted" above).
// ─────────────────────────────────────────────────────────────────

